import{_ as d,C as e,o as s,c as o,j as i,E as n,a as r,a3 as l}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"n":1,"bob":"I-bob · Game Design asoslari","lessons":[{"g":1,"title":"Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar","lead":"O'yin yaratish — bu shunchaki kod yozish yoki rasm chizish emas. Bu insonlar his qiladigan butun boshli yangi olam va unutilmas sarguzashtni barpo etish san'atidir!","link":"/mentor/9-sinf-game/hafta-01/dars-1","slide":"/slaydlar/9-sinf-game/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-01/dars-1-test.html"},{"g":2,"title":"O‘yinlarning tarixi va janrlari: O'yin evolyutsiyasi, janrlar tasnifi va madaniy ta'siri","lead":"O'yinlar insoniyat paydo bo'lganidan beri mavjud. Qadimgi tosh va taxtalardan to bugungi ko'p millionli virtual olamlargacha bo'lgan buyuk evolyutsiya yo'li!","link":"/mentor/9-sinf-game/hafta-01/dars-2","slide":"/slaydlar/9-sinf-game/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-01/dars-2-test.html"},{"g":3,"title":"UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi","lead":"Eng yaxshi o'yin interfeysi — bu o'yinchi sezmaydigan, ammo har qanday vaziyatda unga ko'maklashadigan ko'rinmas do'stdir!","link":"/mentor/9-sinf-game/hafta-01/dars-3","slide":"/slaydlar/9-sinf-game/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-01/index.md","filePath":"mentor/9-sinf-game/hafta-01/index.md"}`),h={name:"mentor/9-sinf-game/hafta-01/index.md"},y={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function v(b,a,f,k,c,q){const t=e("Icon");return s(),o("div",null,[i("div",y,[i("h2",g,[n(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=l('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_1-dars-game-design-faniga-kirish-tushunchasi-ahamiyati-va-dasturiy-vositalar" tabindex="-1">1-dars: Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar <a class="header-anchor" href="#_1-dars-game-design-faniga-kirish-tushunchasi-ahamiyati-va-dasturiy-vositalar" aria-label="Permalink to &quot;1-dars: Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar&quot;">​</a></h2><ol><li>O&#39;zingiz yoqtirgan bitta mobil yoki kompyuter o&#39;yinini tanlang va uning yaratuvchi studiyasini yozing.</li><li>Ushbu o&#39;yinda Game Designer qanday asosiy maqsad qo&#39;yganini (o&#39;yinchi nima qilishi kerakligini) 3 ta jumlada tasvirlang.</li><li>O&#39;yin dizaynining 5 ta komponenti (Gameplay, Level Design, Narratsiya, UI, UX) bo&#39;yicha ushbu o&#39;yinni qisqacha tahlil qiling.</li><li>O&#39;yindagi 3 ta ijobiy dizayn yutug&#39;ini va 1 ta noqulay kamchiligini qayd eting.</li></ol><hr><h2 id="_2-dars-o-yinlarning-tarixi-va-janrlari-o-yin-evolyutsiyasi-va-janrlar-tasnifi" tabindex="-1">2-dars: O‘yinlarning tarixi va janrlari: O&#39;yin evolyutsiyasi va janrlar tasnifi <a class="header-anchor" href="#_2-dars-o-yinlarning-tarixi-va-janrlari-o-yin-evolyutsiyasi-va-janrlar-tasnifi" aria-label="Permalink to &quot;2-dars: O‘yinlarning tarixi va janrlari: O&#39;yin evolyutsiyasi va janrlar tasnifi&quot;">​</a></h2><ol><li>O&#39;zingiz eng ko&#39;p o&#39;ynagan 2 ta o&#39;yinni tanlang.</li><li>Har bir o&#39;yinning aniq janrini (Action, RPG, Strategy, Puzzle, Simulation, Adventure yoki ularning gibridini) belgilang.</li><li>Nima sababdan aynan shu janrga tegishli ekanini har bir o&#39;yindan 3 tadan aniq o&#39;yin mexanikasi misolida asoslab bering.</li><li>Ushbu o&#39;yinlardan birini maktab o&#39;quvchilari uchun ta&#39;limiy o&#39;yinga (Edu-Game) aylantirish bo&#39;yicha 2 ta taklif yozing.</li></ol><hr><h2 id="_3-dars-ui-va-ux-ning-game-designdagi-roli-interfeys-tiplari-va-hud-arxitekturasi" tabindex="-1">3-dars: UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi <a class="header-anchor" href="#_3-dars-ui-va-ux-ning-game-designdagi-roli-interfeys-tiplari-va-hud-arxitekturasi" aria-label="Permalink to &quot;3-dars: UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi&quot;">​</a></h2><ol><li>Sevimli o&#39;yiningizdagi HUD elementlarining to&#39;liq ro&#39;yxatini yozing (Health bar, mini-xarita, qurol, o&#39;q-dorilar, ochkolar).</li><li>O&#39;yindan 4 ta interfeys turiga (Diyegetik, Nodiyegetik, Fazoviy, Meta-interfeys) mos keluvchi 1 tadan aniq element topib, nima uchun aynan shu turga mansubligini tushuntiring.</li><li>O&#39;yindagi 1 ta noqulay interfeys jihatini (yomon UX) tanqid qiling va o&#39;rniga qanday qulay yechim taklif qilishingizni yozing.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>1-dars vazifasi (30 ball):</strong> O&#39;yin dizaynerining roli to&#39;g&#39;ri anglangani va 5 ta komponent (Gameplay, Level Design, Narratsiya, UI, UX) asosida tahlil qilingani.</li><li><strong>2-dars vazifasi (35 ball):</strong> O&#39;yin janrlari va mexanikalari aniq ajratilgani, gibrid janr tushunchasi qo&#39;llangani hamda ta&#39;limiy o&#39;yin g&#39;oyasi taklif etilgani.</li><li><strong>3-dars vazifasi (35 ball):</strong> 4 ta interfeys tipi (Diyegetik, Nodiyegetik, Fazoviy, Meta) to&#39;g&#39;ri tushunilgani va HUD elementlari ergonimikasi asosli tahlil qilingani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchi oddiy o&#39;yinchi nigohi bilan emas, balki bo&#39;lajak Game Designer sifatida tizimli tahlil berganiga alohida e&#39;tibor qarating.</li></ul>',16))]),i("div",m,[i("h2",u,[n(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=l('<p><strong>Mavzular:</strong></p><ol><li>Game Design faniga kirish: tushunchasi, ahamiyati, game designer vazifalari va dasturiy vositalar</li><li>O‘yinlarning tarixi va janrlari: evolyutsiya, janrlar tasnifi (Action, RPG, Strategy, Puzzle) va ta&#39;limiy o&#39;yinlar</li><li>UI va UX ning Game designdagi roli: diyegetik, nodiyegetik, fazoviy, meta interfeyslar va HUD</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Game Design Asoslari</strong></td><td>Game Designer roli, 5 komponent (Gameplay, Level Design, Narratsiya, UI, UX), dvijoklar tanlovi</td><td>30 ball</td></tr><tr><td><strong>O&#39;yinlar Tarixi va Janrlar</strong></td><td>O&#39;yin evolyutsiyasi (Ur, Spacewar, Pong, Tetris), janrlar (Action, RPG, Strategy, Puzzle), RTS vs TBS</td><td>35 ball</td></tr><tr><td><strong>UI/UX va Interfeys Tiplari</strong></td><td>UI vs UX farqi, 4 tip (Diyegetik, Nodiyegetik, Fazoviy, Meta), HUD ergonomikasi va immersiya</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Game Design Asoslari (30)</th><th>Tarix &amp; Janrlar (35)</th><th>UI/UX &amp; Interfeys (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha &quot;O&#39;yin dizayneri&quot; deganda faqat 2D/3D rasm chizadigan rassomni tushunishadi. Game Designer — bu o&#39;yin qoidalari, muvozanati va mexanikasini yaratuvchi bosh arxitektor ekanini turli mashhur o&#39;yinlar misolida ko&#39;rsatish zarur. Shuningdek, 4 xil interfeys turini (ayniqsa fazoviy va meta-interfeys farqini) aniq misollar bilan mustahkamlash lozim.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> O&#39;z g&#39;oyalari bo&#39;yicha to&#39;liq 1 sahifalik GDD (Game Design Document) loyihasini tayyorlash yoki Construct 3 / Godot dvijoklarida dastlabki prototipni sinab ko&#39;rish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const x=d(h,[["render",v]]);export{p as __pageData,x as default};
